{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Celiprolol, which shares the tert-butylamino-hydroxypropoxy aryl urea core with the query, has an absolute oral bioavailability of 30–70% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Practolol, a close aryloxypropanolamine analogue, has an absolute oral bioavailability of 90–100% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Penbutolol, which contains the same tert-butylamino-hydroxypropoxy motif, has an absolute oral bioavailability of 90% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Pafenolol, a urea-containing beta-blocker analogue, has systemic availability of 27–46% across oral doses in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tertatolol, another tert-butylamino beta-blocker, has an absolute oral bioavailability of 60–72% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Prenalterol, a related aryloxypropanolamine, has oral bioavailability values of about 25–42% in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable beta-blocker analogues have absolute oral bioavailability above 20%, with the closest urea- and tert-butylamine-containing analogues (celiprolol, pafenolol, tertatolol) ranging from about 27% to 72%. The query is therefore predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the exact query molecule.",
    "Some analogue values are dose-dependent or variable, but none of the central estimates fall below the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

